const $=s=>document.querySelector(s), h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',book:'M4 4h6l2 2 2-2h6v16h-6l-2 2-2-2H4z M12 6v16',chart:'M4 20V9 M10 20V4 M16 20v-8 M22 20H2',person:'M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 22v-3a8 8 0 0 1 16 0v3',back:'M15 4l-8 8 8 8',refresh:'M20 7a9 9 0 1 0 1 9 M20 2v6h-6',plus:'M12 4v16 M4 12h16',star:'M12 3l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',check:'M4 12l5 5L20 6',code:'M8 5l-6 7 6 7 M16 5l6 7-6 7 M14 3l-4 18',play:'M7 3l15 9-15 9z',upload:'M12 17V3 M6 9l6-6 6 6 M4 15v6h16v-6',folder:'M2 6h8l2 3h10v12H2z',more:'M4 12h.1 M12 12h.1 M20 12h.1',close:'M5 5l14 14 M19 5L5 19'};
